export class AgentsWorkflowResource extends APIResource {
  /**
   * Get the agent's workflow draft, with validation
   *
   * `GET /v1/agents/{id}/workflow/draft`
   */
  retrieveDraft(agentId: string, options?: RequestOptions): Promise<WorkflowDraft> {
    return this._client.request<WorkflowDraft>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/workflow/draft`, options });
  }

  /**
   * Save the agent's workflow draft
   *
   * Creates or replaces the draft. Drafts may be incomplete: problems come back in `validation.errors`, pinned to node ids, and block publishing but not saving.
   *
   * `PUT /v1/agents/{id}/workflow/draft`
   */
  updateDraft(agentId: string, params: SaveWorkflowDraftRequest, options?: RequestOptions): Promise<WorkflowDraft> {
    return this._client.request<WorkflowDraft>({ method: "PUT", path: `/v1/agents/${encodePath(agentId)}/workflow/draft`, body: params, options });
  }

  /**
   * Validate a workflow graph without saving it
   *
   * `POST /v1/agents/{id}/workflow/validate`
   */
  validate(agentId: string, params?: ValidateWorkflowRequest, options?: RequestOptions): Promise<WorkflowValidation> {
    return this._client.request<WorkflowValidation>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/validate`, body: params ?? {}, options });
  }

  /**
   * Publish the draft as a new immutable version
   *
   * Moves every active deployment of the agent onto the new version. Responds 422 (`invalid_workflow`, with `details.errors`) if the draft has problems.
   *
   * `POST /v1/agents/{id}/workflow/draft/publish`
   */
  publishDraft(agentId: string, params?: AgentWorkflowPublishDraftParams, options?: RequestOptions): Promise<AgentDetail> {
    return this._client.request<AgentDetail>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/draft/publish`, body: params ?? {}, options });
  }

  /**
   * The deployed workflow graph, to start a draft from
   *
   * The live graph as it runs, with transfer targets and other workspace values kept. Use the export to share a workflow instead.
   *
   * `GET /v1/agents/{id}/workflow/published`
   */
  retrievePublished(agentId: string, options?: RequestOptions): Promise<PublishedWorkflow> {
    return this._client.request<PublishedWorkflow>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/workflow/published`, options });
  }

  /**
   * Download the workflow as a .lassi-workflow.json file
   *
   * Phone numbers, CRM field ids and knowledge base ids are removed and listed in `needs_setup`.
   *
   * `GET /v1/agents/{id}/workflow/export`
   */
  export(agentId: string, params?: AgentWorkflowExportParams, options?: RequestOptions): Promise<WorkflowFile> {
    return this._client.request<WorkflowFile>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/workflow/export`, query: params, options });
  }

  /**
   * Import a .lassi-workflow.json file into the agent's draft
   *
   * Replaces the draft. Fields the agent already has keep its own definition; new ones are added. Anything listed in `needs_setup` must be filled in before publishing.
   *
   * `POST /v1/agents/{id}/workflow/import`
   */
  import(agentId: string, params: WorkflowFile, options?: RequestOptions): Promise<WorkflowImportResult> {
    return this._client.request<WorkflowImportResult>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/import`, body: params, options });
  }

  /**
   * Build or edit the workflow with AI
   *
   * Takes the conversation so far and the graph on the canvas, and returns the assistant's reply with an updated graph. The graph always passes validation (or is null when the reply only answers a question). Nothing is saved: the editor applies it to the draft.
   *
   * `POST /v1/agents/{id}/workflow/assist`
   */
  assist(agentId: string, params: WorkflowAssistRequest, options?: RequestOptions): Promise<WorkflowAssistResult> {
    return this._client.request<WorkflowAssistResult>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/assist`, body: params, options });
  }

  /**
   * Start a Build with AI request in the background
   *
   * Like POST /agents/{id}/workflow/assist, but returns at once and keeps working if the caller goes away. Poll GET /agents/{id}/workflow/assist-runs for the answer. One run per agent at a time.
   *
   * `POST /v1/agents/{id}/workflow/assist-runs`
   */
  startAssistRun(agentId: string, params: StartAssistRunRequest, options?: RequestOptions): Promise<AssistRun> {
    return this._client.request<AssistRun>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/assist-runs`, body: params, options });
  }

  /**
   * Recent Build with AI requests
   *
   * The last day's runs on this agent, oldest first (at most 20).
   *
   * `GET /v1/agents/{id}/workflow/assist-runs`
   */
  listAssistRuns(agentId: string, options?: RequestOptions): Promise<AgentWorkflowListAssistRunsResponse> {
    return this._client.request<AgentWorkflowListAssistRunsResponse>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/workflow/assist-runs`, options });
  }

  /**
   * Mark a run's answer as applied to the draft
   *
   * `POST /v1/agents/{id}/workflow/assist-runs/{runId}/applied`
   */
  markAssistRunApplied(agentId: string, runId: string, options?: RequestOptions): Promise<AssistRun> {
    return this._client.request<AssistRun>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/assist-runs/${encodePath(runId)}/applied`, options });
  }

  /**
   * Put back the agent settings a run saved
   *
   * Undo for the business settings a Build with AI answer saved (business name, business facts, hours callers hear, Spanish). Each goes back to what it held before, unless it was changed since: those are kept and listed in `kept`. Once only.
   *
   * `POST /v1/agents/{id}/workflow/assist-runs/{runId}/undo-settings`
   */
  undoAssistRunSettings(agentId: string, runId: string, options?: RequestOptions): Promise<AgentWorkflowUndoAssistRunSettingsResponse> {
    return this._client.request<AgentWorkflowUndoAssistRunSettingsResponse>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/assist-runs/${encodePath(runId)}/undo-settings`, options });
  }

  /**
   * Test a Custom Code step
   *
   * Runs code in the same sandbox calls use, with sample answers and the agent's business settings (sample `variables` win), and returns what it returned or what went wrong. Nothing is saved.
   *
   * `POST /v1/agents/{id}/workflow/code/test`
   */
  testCode(agentId: string, params: TestCodeRequest, options?: RequestOptions): Promise<CodeRunResult> {
    return this._client.request<CodeRunResult>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/workflow/code/test`, body: params, options });
  }
}

export class AgentsVersionsResource extends APIResource {
  /**
   * List the agent's published workflow versions
   *
   * Newest first. Versions are immutable once published.
   *
   * `GET /v1/agents/{id}/versions`
   */
  list(agentId: string, options?: RequestOptions): Promise<AgentVersionListResponse> {
    return this._client.request<AgentVersionListResponse>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/versions`, options });
  }

  /**
   * Get one published version, with what it runs
   *
   * `GET /v1/agents/{id}/versions/{v}`
   */
  retrieve(agentId: string, version: number, options?: RequestOptions): Promise<WorkflowVersion> {
    return this._client.request<WorkflowVersion>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/versions/${encodePath(version)}`, options });
  }

  /**
   * Compare two published versions
   *
   * What changed from version `a` to version `b`: steps added, removed and changed (with each changed key, prompt text included), the flow, and the version's settings.
   *
   * `GET /v1/agents/{id}/versions/{a}/diff/{b}`
   */
  diff(agentId: string, fromVersion: number, toVersion: number, options?: RequestOptions): Promise<WorkflowVersionDiff> {
    return this._client.request<WorkflowVersionDiff>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/versions/${encodePath(fromVersion)}/diff/${encodePath(toVersion)}`, options });
  }

  /**
   * Roll back to a published version
   *
   * Publishes version `v`'s content as a new version, changelog "Rolled back to v{v}", and moves the agent's deployments onto it. Old versions are never changed. The same checks as a publish apply: the graph is validated against today's rules (422 `invalid_workflow`), its calendars must still be connected, and an agent whose publish check blocks refuses it (409 `publish_check_blocks_rollback`). 409 `version_live` when `v` is already live. The agent's prompt, greetings and voice aren't part of a version and don't change.
   *
   * `POST /v1/agents/{id}/versions/{v}/restore`
   */
  restore(agentId: string, version: number, options?: RequestOptions): Promise<AgentDetail> {
    return this._client.request<AgentDetail>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/versions/${encodePath(version)}/restore`, options });
  }
}

