export class AgentsResource extends APIResource {
  readonly tools: AgentsToolsResource = new AgentsToolsResource(this._client);

  readonly tests: AgentsTestsResource = new AgentsTestsResource(this._client);

  readonly guardrails: AgentsGuardrailsResource = new AgentsGuardrailsResource(this._client);

  readonly workflow: AgentsWorkflowResource = new AgentsWorkflowResource(this._client);

  readonly versions: AgentsVersionsResource = new AgentsVersionsResource(this._client);

  readonly knowledgeBases: AgentsKnowledgeBasesResource = new AgentsKnowledgeBasesResource(this._client);

  readonly scripts: AgentsScriptsResource = new AgentsScriptsResource(this._client);

  /**
   * List agents
   *
   * `GET /v1/agents`
   */
  list(options?: RequestOptions): Promise<AgentListResponse> {
    return this._client.request<AgentListResponse>({ method: "GET", path: `/v1/agents`, options });
  }

  /**
   * Create an agent
   *
   * Creates the agent with a published workflow, optionally started from a template. It can be tested in the browser right away; give it a phone number to take real calls.
   *
   * `POST /v1/agents`
   */
  create(params: CreateAgentRequest, options?: RequestOptions): Promise<AgentDetail> {
    return this._client.request<AgentDetail>({ method: "POST", path: `/v1/agents`, body: params, options });
  }

  /**
   * Get an agent with its deployed workflow, versions and numbers
   *
   * `GET /v1/agents/{id}`
   */
  retrieve(agentId: string, options?: RequestOptions): Promise<AgentDetail> {
    return this._client.request<AgentDetail>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}`, options });
  }

  /**
   * Rename an agent
   *
   * The name is a label in the dashboard; callers hear the persona's name. Takes effect immediately and isn't part of the versioned config.
   *
   * `PATCH /v1/agents/{id}`
   */
  update(agentId: string, params: RenameAgentRequest, options?: RequestOptions): Promise<Agent> {
    return this._client.request<Agent>({ method: "PATCH", path: `/v1/agents/${encodePath(agentId)}`, body: params, options });
  }

  /**
   * Delete an agent
   *
   * Its numbers stop answering for it straight away (they stay in the workspace, free to give to another agent), and it's detached from knowledge bases and scripts. Past calls keep their transcripts and still show the agent's name. Can't be undone from the dashboard.
   *
   * `DELETE /v1/agents/{id}`
   */
  delete(agentId: string, options?: RequestOptions): Promise<void> {
    return this._client.request<void>({ method: "DELETE", path: `/v1/agents/${encodePath(agentId)}`, responseType: "empty", options });
  }

  /**
   * Save edits and publish a new immutable version to the agent's deployments
   *
   * `POST /v1/agents/{id}/publish`
   */
  publish(agentId: string, params?: PublishAgentRequest, options?: RequestOptions): Promise<AgentDetail> {
    return this._client.request<AgentDetail>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/publish`, body: params ?? {}, options });
  }

  /**
   * Choose the team alerted about this agent's urgent calls
   *
   * Takes effect immediately; not part of the versioned agent config.
   *
   * `PUT /v1/agents/{id}/notifications`
   */
  updateNotifications(agentId: string, params: AgentNotifications, options?: RequestOptions): Promise<AgentNotifications> {
    return this._client.request<AgentNotifications>({ method: "PUT", path: `/v1/agents/${encodePath(agentId)}/notifications`, body: params, options });
  }

  /**
   * Set the rules each of this agent's calls is judged against
   *
   * Takes effect from the next call; calls already judged keep the criteria they were judged on. Not part of the versioned agent config.
   *
   * `PUT /v1/agents/{id}/success-criteria`
   */
  updateSuccessCriteria(agentId: string, params: AgentSuccessCriteria, options?: RequestOptions): Promise<AgentSuccessCriteria> {
    return this._client.request<AgentSuccessCriteria>({ method: "PUT", path: `/v1/agents/${encodePath(agentId)}/success-criteria`, body: params, options });
  }

  /**
   * Change some of the agent's business settings (variables)
   *
   * Sets these variables and keeps the rest. Like the settings Build with AI saves, they're facts about the business: the next call uses them, without publishing a new version.
   *
   * `PATCH /v1/agents/{id}/variables`
   */
  updateVariables(agentId: string, params: AgentVariablesUpdate, options?: RequestOptions): Promise<AgentVariables> {
    return this._client.request<AgentVariables>({ method: "PATCH", path: `/v1/agents/${encodePath(agentId)}/variables`, body: params, options });
  }

  /**
   * Set or turn off the agent's pre-call webhook
   *
   * When a call rings, Ladoo POSTs `{call_id, agent_id, kind, from, to, person}` to this URL and waits up to 1 second for `{variables, caller, note_for_agent, route}`. A slow, failing or unreadable reply leaves the call as usual. The first URL creates a signing secret, returned once; changing the URL keeps it. Needs `webhooks:write` as well, like a webhook endpoint, since it sends callers' details out.
   *
   * `PUT /v1/agents/{id}/pre-call-webhook`
   */
  updatePreCallWebhook(agentId: string, params: PreCallWebhookUpdate, options?: RequestOptions): Promise<PreCallWebhookSaved> {
    return this._client.request<PreCallWebhookSaved>({ method: "PUT", path: `/v1/agents/${encodePath(agentId)}/pre-call-webhook`, body: params, options });
  }

  /**
   * Rotate the pre-call webhook's signing secret
   *
   * Returns the new secret, shown only once. The old one stops signing at once.
   *
   * `POST /v1/agents/{id}/pre-call-webhook/rotate-secret`
   */
  rotatePreCallWebhookSecret(agentId: string, options?: RequestOptions): Promise<PreCallWebhookSaved> {
    return this._client.request<PreCallWebhookSaved>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/pre-call-webhook/rotate-secret`, options });
  }

  /**
   * Edit the agent's prompt, greetings and details with AI
   *
   * Takes the conversation so far and the agent as it is in the editor, and returns the assistant's reply with the updated draft. Fields and settings can be added or changed, never removed. Nothing is saved: the editor applies it as unsaved changes. Costs one Build with AI message.
   *
   * `POST /v1/agents/{id}/assist`
   */
  assist(agentId: string, params: AgentAssistRequest, options?: RequestOptions): Promise<AgentAssistResponse> {
    return this._client.request<AgentAssistResponse>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/assist`, body: params, options });
  }

  /**
   * Set the agent up with AI
   *
   * Reads the agent's knowledge (waiting for sources still being read), writes its prompt, greeting and fields, then builds and publishes its workflow, in the background. Poll GET /agents/{id}/build. Costs up to two Build with AI messages.
   *
   * `POST /v1/agents/{id}/build`
   */
  startBuild(agentId: string, params: StartAgentBuildRequest, options?: RequestOptions): Promise<AgentBuild> {
    return this._client.request<AgentBuild>({ method: "POST", path: `/v1/agents/${encodePath(agentId)}/build`, body: params, options });
  }

  /**
   * The agent's latest AI setup
   *
   * `GET /v1/agents/{id}/build`
   */
  retrieveBuild(agentId: string, options?: RequestOptions): Promise<AgentBuild> {
    return this._client.request<AgentBuild>({ method: "GET", path: `/v1/agents/${encodePath(agentId)}/build`, options });
  }
}

